import type { ChainId } from './chains';

import { workMultiLines, workRequestLines, workThanksLines } from './lines-work';

export type Role = 'flatmate' | 'tutor' | 'work';

/**
 * Each character's avatar art is assets/avatars/{id}.svg, generated by scripts/avatars.mjs.
 * Who messages you depends on the stage and path (see paths.ts).
 */
export interface Character {
  id: string;
  name: string;
  /** Shown after the name, like a team in a work chat. */
  team: string;
  role: Role;
}

