export const deliverLines = ['Here you go!', 'Sorted.', 'Done and done.', 'Fresh off the board.', 'On your desk.'];

export const FALLBACK: ChatLine[] = [{ text: 'Could you sort this out for me?' }];

/** Work-flavoured requests for the Uni chains, which stay on the board for the rest of your career. */
const workUniLines: Record<string, ChatLine[]> = {
  'study-1': [{ role: 'work', text: 'Anyone got a highlighter? Reviewing the contract' }],
  'study-2': [{ role: 'work', text: 'Did anyone take notes in that meeting? Anyone?' }],
  'study-3': [{ role: 'work', text: 'Making flashcards for the all-hands acronyms' }],
  'study-4': [{ role: 'work', text: 'Need a write-up. Long enough that nobody reads it' }],
  'study-5': [{ role: 'work', text: 'Certification exam tomorrow. Send help' }],
  'study-6': [{ role: 'work', text: 'Framing a degree for the office wall. Credibility' }],
  'food-1': [{ role: 'work', text: 'Desk lunch again. Noodles, please' }],
  'food-2': [{ role: 'work', text: 'Working through lunch. A toastie would save me' }],
  'food-3': [{ role: 'work', text: 'Is there any pizza left from the launch?' }],
  'food-4': [{ role: 'work', text: 'Lunch-and-learn needs a whole pizza. For learning' }],
  'food-5': [{ role: 'work', text: 'Late night ship. Order the usual pizzas' }],
  'food-6': [{ role: 'work', text: 'Someone’s leaving. Cake. Now.' }],
};

const say = (l: ChatLine, who: Character) => (!l.role || l.role === who.role) && (!l.who || l.who.includes(who.id));

export function linesFor(chain: ChainId, tier: number, who: Character): ChatLine[] {
  const key = `${chain}-${tier}`;
  const all = [...(requestLines[key as `${ChainId}-${number}`] ?? []), ...(workUniLines[key] ?? []), ...(workRequestLines[key] ?? [])];
  const matching = all.filter((l) => say(l, who));
  return matching.length ? matching : FALLBACK;
}

export function multiLinesFor(who: Character): ChatLine[] {
  const own = (workMultiLines[who.id] ?? []).map((text) => ({ text }));
  const all = [...multiLines.filter((l) => say(l, who)), ...own];
  return all.length ? all : FALLBACK;
}

export function thanksLinesFor(who: Character): ChatLine[] {
  const own = (workThanksLines[who.id] ?? []).map((text) => ({ text }));
  const all = [...thanksLines.filter((l) => say(l, who)), ...own];
  return all.length ? all : FALLBACK;
}
